const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=[{id:'REQ-024',title:'Bring SSO forward for the Acme deal',description:'Find a delivery plan that unlocks our enterprise deal without putting the platform roadmap at risk.',status:'review',stage:5,kind:'sso',comments:[]},{id:'REQ-023',title:'Align on Q4 analytics priorities',description:'Agree on a focused reporting scope for the next release.',status:'active',stage:0,kind:'analytics',comments:[]},{id:'REQ-022',title:'Customer onboarding handoff',description:'A shared onboarding checklist with clear team ownership.',status:'done',stage:5,kind:'onboarding',comments:[]}];
let requests;try{requests=JSON.parse(localStorage.getItem('accord-requests'))||structuredClone(initial)}catch{requests=structuredClone(initial)}let selected=requests[0].id,filter='all',view='requests',tab='conversation',running=false;let timers=[];
const sources=[{title:'Acme · Enterprise opportunity',type:'CRM · Business scope',date:'Updated Oct 17, 2026',quote:'Acme represents $120,000 in annual recurring revenue. Their security review requires SAML SSO for 50 pilot users by November 15. SCIM provisioning is not required for the pilot.',boundary:'Shareable: deal value and pilot requirements. Private: pricing terms, contacts, and negotiation notes.',team:'Business'},{title:'Platform planning · Q4',type:'Planning document · Engineering scope',date:'Updated Oct 17, 2026',quote:'Two engineers are available for the identity workstream. SAML-only pilot: estimated 10 engineer-days plus 3 days of security review and contingency. Full SSO and SCIM: 25 engineer-days. Moving the dashboard refresh frees the required capacity.',boundary:'Shareable: estimates, dependencies, and roadmap impact. Private: individual performance and internal incident details.',team:'Engineering'},{title:'Identity service · Issue #142',type:'GitHub · Engineering scope',date:'Sample snapshot · Oct 17, 2026',quote:'SAML authentication foundation is merged. Remaining work: tenant configuration, identity-provider callback validation, audit events, integration tests, and security review. SCIM is tracked separately in #168.',boundary:'Shareable: implementation status and blockers. Private: source code, credentials, and vulnerability details.',team:'Engineering'},{title:'Acme discovery · Meeting notes',type:'Transcript · Business scope',date:'Meeting held Oct 16, 2026',quote:'The customer confirmed a pilot with one identity provider is acceptable. Business can commit to a November 15 pilot rather than general availability, provided the security review passes.',boundary:'Shareable: confirmed customer acceptance criteria. Private: raw transcript and customer personal information.',team:'Business'}];
const r=()=>requests.find(x=>x.id===selected);const save=()=>localStorage.setItem('accord-requests',JSON.stringify(requests));const status=x=>x.status==='done'?'Approved':x.stage>=5?'Needs approval':x.stage>0?'Negotiating':'Ready to start';const pill=x=>`<span class="pill ${x.status==='done'?'done':x.stage>=5?'review':''}">${status(x)}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}function source(i){const s=sources[i];modal(`<div class="eyebrow">SOURCE EVIDENCE · SAMPLE DATA</div><h2>${s.title}</h2><p>${s.type} · ${s.date}</p><div class="quote">${s.quote}</div><div class="boundary">◈ ${s.boundary}</div><p>Each agent reads its own team’s sources. This demo displays the permitted excerpt that was shared in the negotiation.</p>`)}
function render(){save();$('#active-stat').textContent=requests.filter(x=>x.status!=='done').length;$('#agreement-stat').textContent=requests.filter(x=>x.status==='done').length;$('#request-count').textContent=requests.length;$('#list-count').textContent=requests.length;$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${view==='agreements'?'Agreements':view==='sources'?'Knowledge sources':'Requests'}`;$('#list-title').firstChild.textContent=view==='agreements'?'Agreements ':'Requests ';document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));let visible=requests.filter(x=>(view!=='agreements'||x.status==='done')&&(filter==='all'||(filter==='done'?x.status==='done':x.status!=='done')));$('#request-items').innerHTML=visible.map(x=>`<button class="request-card ${x.id===selected?'selected':''}" data-id="${x.id}"><div class="request-meta"><span>${x.id}</span>${pill(x)}</div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="request-teams"><span class="mini business">↗</span> Business <span>⇄</span><span class="mini engineering">⌘</span> Engineering</div></button>`).join('')||'<div class="empty">No requests in this view yet.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{if(running)return toast('Wait for this negotiation to finish.');selected=b.dataset.id;tab='conversation';render()});if(view==='sources'){renderSources();return}if(view==='agreements'&&!visible.some(x=>x.id===selected)){if(visible[0])selected=visible[0].id;else{$('#detail').innerHTML='<div class="empty">Approved agreements will appear here.</div>';return}}renderDetail()}
function renderDetail(){const x=r();$('#detail').innerHTML=`<div class="detail-heading"><div class="detail-topline"><span>${x.id} <span style="margin:0 7px">/</span> Business → Engineering</span>${pill(x)}</div><h2>${esc(x.title)}</h2><div class="detail-description">${esc(x.description)}</div><div class="participant-row"><span class="avatar business">M</span><span class="avatar engineering">T</span><span>Maya & Theo <span style="color:#b1b9a5">· 2 team agents</span></span><span class="scope">◈ Scoped knowledge</span></div></div><div class="detail-tabs"><button data-tab="conversation" class="${tab==='conversation'?'active':''}">Conversation <b>${Math.min(x.stage+1,6)+x.comments.length}</b></button><button data-tab="agreement" class="${tab==='agreement'?'active':''}">Agreement ${x.stage>=5?'<b>1</b>':''}</button><button data-tab="evidence" class="${tab==='evidence'?'active':''}">Evidence <b>${x.kind==='sso'?4:2}</b></button></div><div id="tab-content"></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderDetail()});if(tab==='agreement')renderAgreement();else if(tab==='evidence')renderEvidence();else renderThread()}
function msg(name,role,body,refs=[],human=false){return `<div class="message"><span class="avatar ${human?'human':role==='Business'?'business':'engineering'}">${human?'JD':name[0]}</span><div class="message-body"><div class="message-name">${name}<span class="agent-tag">${human?'Requester':role+' agent'}</span><span class="time">${human?'10:24 AM':'10:25 AM'}</span></div><p>${body}</p>${refs.map(i=>`<button class="citation" data-source="${i}">▧ ${sources[i].title} ↗</button>`).join('')}</div></div>`}
function renderThread(){const x=r(),sso=x.kind==='sso';let h=`<div class="thread"><div class="date-line">October 17, 2026 <span style="padding:0 6px">·</span> ${running?'Negotiation in progress':'A conversation with shared context'}</div>`;h+=msg('Jamie Davis','',sso?'Can we bring SSO forward to <strong>November 15</strong>? It’s the last blocker for the Acme enterprise deal. Let’s find a realistic plan with Engineering.':esc(x.description),[],true);const sequence=sso?[
['Maya','Business','I’ve reviewed the opportunity and discovery notes. This is a <strong>$120k ARR opportunity</strong>, and the customer needs SAML SSO for a 50-user pilot. Theo, what would it take to deliver a focused version by November 15?',[0,3]],
['Theo','Engineering','The SAML foundation is already merged. The full SSO + SCIM scope won’t fit, but a <strong>SAML-only pilot needs 10 engineer-days</strong>, plus security review. We can make room by moving the dashboard refresh. Is SCIM essential to closing?',[1,2]],
['Maya','Business','Confirmed in the customer call: <strong>SCIM is not required for the pilot</strong>. One identity provider and 50 users are enough. Business can position November 15 as a pilot, with general availability agreed separately.',[3]],
['Theo','Engineering','That works with the planning estimate. I propose a SAML-only pilot by <strong>November 15, conditional on security sign-off</strong>. Defer the dashboard refresh to November 29, with Engineering owning implementation and Business owning customer expectations.',[1,2]],
['Maya','Business','Aligned. The narrower scope meets the customer’s acceptance criteria and protects the engineering buffer. I’ve drafted an agreement for <strong>both team leads to review</strong>.',[0,3]]]:[
['Maya','Business','The key outcome is a focused, usable first release. Let’s keep the initial scope small and identify the tradeoffs explicitly.',[0]],['Theo','Engineering','I can propose a phased delivery. We’ll assign an engineering owner, validate the estimate, and preserve time for review.',[1]],['Maya','Business','Agreed. Business will confirm acceptance criteria before work begins, and communicate the phased scope to stakeholders.',[]],['Theo','Engineering','Proposal: a two-week discovery and implementation window after both leads approve, with a checkpoint after the first week.',[1]],['Maya','Business','The proposal is ready for human review. Dates and scope remain provisional until the team leads sign off.',[]]];
sequence.slice(0,x.stage).forEach(m=>h+=msg(...m));x.comments.forEach(c=>h+=msg('Jamie Davis','',esc(c),[],true));if(x.stage>=5){h+='<div class="system-line">✧ A shared proposal is ready</div><div class="agreement-preview"><div class="label">◇ PROPOSED AGREEMENT</div><h3>'+ (sso?'A focused pilot. A protected roadmap.':'A phased delivery with clear ownership.')+'</h3><p>'+ (sso?'SAML SSO pilot by Nov 15 · 50 users · Security sign-off required':'Two-week delivery window · Weekly checkpoint · Team lead sign-off')+'</p><div class="actions"><button class="primary" id="review">'+(x.status==='done'?'View approved agreement':'Review agreement')+' →</button><button class="outline" id="evidence-btn">View evidence</button></div></div>'}h+='</div>';if(x.stage===0)h+='<div class="start-box"><h3>Two perspectives. One shared outcome.</h3><p>Maya and Theo will review their scoped evidence, discuss tradeoffs, and draft a proposal for your approval.</p><button class="primary" id="start">✧ Start agent negotiation</button></div>';if(running)h+='<div class="typing">✧ Agents are reviewing the evidence and responding…</div>';h+=`<form class="composer" id="comment-form"><textarea aria-label="Add context" placeholder="Add context or guide the conversation…" required maxlength="2000"></textarea><div class="composer-bottom"><span>Only share information appropriate for both teams.</span><button type="submit" aria-label="Send message">↑</button></div></form>`;$('#tab-content').innerHTML=h;bindSources();if($('#review'))$('#review').onclick=()=>{tab='agreement';renderDetail()};if($('#evidence-btn'))$('#evidence-btn').onclick=()=>{tab='evidence';renderDetail()};if($('#start'))$('#start').onclick=start;$('#comment-form').onsubmit=e=>{e.preventDefault();let text=e.target.querySelector('textarea').value.trim();if(!text)return;x.comments.push(text);render();toast('Context added to the shared conversation.')};}
function start(){if(running)return;running=true;const x=r();x.status='active';for(let n=1;n<=5;n++)timers.push(setTimeout(()=>{x.stage=n;if(n===5){running=false;x.status='review';toast('Negotiation complete. The proposal is ready for review.')}render()},n*1600));render()}
function renderAgreement(){const x=r();if(x.stage<5){$('#tab-content').innerHTML='<div class="empty">An agreement will appear after the agents finish negotiating.</div>';return}const sso=x.kind==='sso';$('#tab-content').innerHTML=`<div class="content-panel"><div class="eyebrow">◇ ${x.status==='done'?'APPROVED AGREEMENT':'DRAFT · HUMAN APPROVAL REQUIRED'}</div><h3 style="margin-top:12px">${sso?'A focused pilot. A protected roadmap.':'A phased plan with clear ownership.'}</h3><p>${sso?'Deliver the essential customer outcome while making the capacity tradeoff explicit.':'Start with a focused scope and validate progress together at a shared checkpoint.'}</p><div class="agreement-grid"><div><small>DELIVERABLE</small><strong>${sso?'SAML SSO · 1 provider · 50 users':'Focused first release'}</strong></div><div><small>TARGET</small><strong>${sso?'November 15, 2026':'Two weeks after approval'}</strong></div><div><small>BUSINESS VALUE</small><strong>${sso?'Unblocks $120,000 ARR opportunity':'Clear acceptance criteria'}</strong></div><div><small>TRADEOFF</small><strong>${sso?'Dashboard refresh → November 29':'Defer nonessential scope'}</strong></div></div><h3>Owners & conditions</h3><p>Engineering lead: delivery, testing, and security review.<br>Business lead: customer expectations and acceptance.<br>${sso?'SCIM and general availability are outside this pilot. Security sign-off is required before launch.':'Both leads must validate scope and capacity before work starts.'}</p><div class="boundary">${sso?'Estimate: 10 engineer-days plus review and contingency. A new blocker or expanded scope requires a revised agreement.':'This is a sample proposal. Timing requires team validation.'}</div>${x.status==='done'?'<div class="approve-banner">✓ Approved by Jamie Davis · Recorded locally in this demo</div><button class="outline" id="export">↓ Export agreement</button>':'<div class="actions"><button class="primary" id="approve">✓ Approve proposal</button><button class="outline" id="revise">Request revision</button></div><p style="font-size:10px">Demo approval records your decision locally. No external tickets are created.</p>'}</div>`;if($('#approve'))$('#approve').onclick=()=>{x.status='done';render();toast('Agreement approved and recorded.');};if($('#revise'))$('#revise').onclick=revision;if($('#export'))$('#export').onclick=()=>{const text=`ACCORD AGREEMENT\n${x.id}: ${x.title}\nStatus: Approved\n\n${$('#tab-content').innerText}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=x.id+'-agreement.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function revision(){modal('<h2>Request a revision</h2><p>Explain what should change before the team commits.</p><form id="revision-form"><label for="revision">Revision notes</label><textarea id="revision" required maxlength="2000" placeholder="e.g. Keep the dashboard refresh in the current release."></textarea><button class="primary">Send revision request</button></form>');$('#revision-form').onsubmit=e=>{e.preventDefault();const note=$('#revision').value.trim();if(!note)return;r().comments.push('Revision requested: '+note);r().stage=0;r().status='active';$('#modal').close();tab='conversation';render();toast('Revision recorded. Restart negotiation to replay the sample proposal.')}}
function bindSources(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>source(Number(b.dataset.source)))}function renderEvidence(){const indexes=r().kind==='sso'?[0,1,2,3]:[0,1];$('#tab-content').innerHTML='<div class="content-panel"><h3>Evidence behind the discussion</h3><p>Permitted excerpts shared by each team’s agent. All records are sample data.</p>'+indexes.map(i=>`<button class="source-card" data-source="${i}" style="width:100%;text-align:left;background:white"><strong>▧ ${sources[i].title} ↗</strong><small>${sources[i].type}</small></button>`).join('')+'</div>';bindSources()}
function renderSources(){$('#detail').innerHTML='<div class="content-panel"><div class="eyebrow">SCOPED KNOWLEDGE</div><h3 style="margin-top:10px">Connected context, clear boundaries.</h3><p>This demo uses curated snapshots. Live GitHub, CRM, and transcript integrations are not connected.</p>'+sources.map((s,i)=>`<button class="source-card" data-source="${i}" style="width:100%;text-align:left;background:white"><strong>▧ ${s.title} ↗</strong><small>${s.type} · ${s.date}</small></button>`).join('')+'<div class="boundary">◈ Maya can read Business sources. Theo can read Engineering sources. Only permitted summaries enter the shared thread. Access boundaries are illustrative in this browser-only demo.</div></div>';bindSources()}
function newRequest(){modal('<div class="eyebrow">LET YOUR AGENTS FIND COMMON GROUND</div><h2>Start a shared request</h2><p>Describe an outcome. Business and Engineering will work through the tradeoffs.</p><form id="new-form"><label for="title">Request title</label><input id="title" required maxlength="120" placeholder="e.g. Launch a customer reporting pilot"><label for="description">Outcome & constraints</label><textarea id="description" required maxlength="1500" placeholder="What do you need, by when, and why does it matter?"></textarea><label for="scenario">Demo negotiation</label><select id="scenario"><option value="sso">SSO enterprise pilot — evidence-backed scenario</option><option value="custom">General request — sample phased proposal</option></select><p style="font-size:10px">Negotiations are scripted for the demo. Custom text is recorded, but does not drive AI reasoning.</p><button class="primary">Create request →</button></form>');$('#new-form').onsubmit=e=>{e.preventDefault();const title=$('#title').value.trim(),description=$('#description').value.trim();if(!title||!description)return;const x={id:'REQ-'+String(Math.max(...requests.map(x=>Number(x.id.slice(4))))+1).padStart(3,'0'),title,description,kind:$('#scenario').value==='sso'?'sso':'custom',status:'active',stage:0,comments:[]};requests.unshift(x);selected=x.id;view='requests';filter='all';tab='conversation';$('#modal').close();document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));render();toast('Request created. Start the negotiation when ready.')};}
$('#new-request').onclick=newRequest;$('.modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(running)return toast('Wait for this negotiation to finish.');view=b.dataset.view;filter='all';document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));render()});$('#filter').onclick=()=>{filter=filter==='active'?'all':'active';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.filter===filter));render()};$('#reset').onclick=()=>{modal('<h2>Reset the demo?</h2><p>This will remove local requests, comments, and approvals and restore the sample workspace.</p><button class="primary" id="confirm-reset">Reset workspace</button>');$('#confirm-reset').onclick=()=>{timers.forEach(clearTimeout);timers=[];running=false;requests=structuredClone(initial);selected=requests[0].id;view='requests';filter='all';tab='conversation';$('#modal').close();document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.filter==='all'));render();toast('Sample workspace restored.')}};$('#how').onclick=()=>modal('<div class="eyebrow">HOW ACCORD WORKS</div><h2>From request to agreement.</h2><p><strong>1. Give each team its context.</strong><br>Agents use scoped sources to understand goals and constraints.</p><p><strong>2. Let the evidence lead.</strong><br>Agents clarify requirements, cite facts, and propose tradeoffs in a visible thread.</p><p><strong>3. Keep people in control.</strong><br>Review the scope, owners, risks, and displaced work before approving.</p><div class="boundary">This prototype uses scripted agents and sample evidence. All changes are saved only in your browser. It does not make live AI calls or enforce server-side permissions.</div>');document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{const business=b.dataset.team==='Business';modal(`<div class="eyebrow">${business?'BUSINESS':'ENGINEERING'} TEAM</div><h2>${business?'Maya':'Theo'} · Your team’s agent</h2><p>${business?'Represents customer needs, commercial impact, and business priorities.':'Represents delivery constraints, implementation status, and engineering tradeoffs.'}</p><div class="quote">${business?'Can access: CRM opportunity summaries and customer discovery notes.':'Can access: repository activity and engineering planning estimates.'}<br>Cannot access: the other team’s private sources.</div><p>Allowed disclosures are represented by curated excerpts in this demo. Live permissions and integrations would be implemented in a backend.</p>`)});$('#activity').onclick=()=>modal('<h2>Workspace activity</h2><p>Today · Sample workspace initialized.</p>'+requests.filter(x=>x.status==='done').map(x=>`<p>✓ ${esc(x.title)} — approved agreement</p>`).join('')+'<p>Agent activity and approvals in this demo are stored in your browser.</p>');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();newRequest()}});render();
